      gpuMax: st.gpuMax,
      cpuCells: st.cpuCells,
      cpuMax: st.cpuMax,
      cpuAssigned: st.cpuAssigned,
      cpuMs: st.cpuMs,
      camH: st.camH,
      zoom: st.zoom,
      deckPitch: st.deckPitch,
      bearing: st.bearing,
      cesiumPitchDeg: st.cesiumPitchDeg,
