import {
  CAT_KEYS,
  DEFAULT_CAT_COLORS,
  TARGET_CATS as CATS,
  isCustomColor,
  layoutTargets,
  layoutChecksum,
  nextSeed,
  normalizeHex,
  resolveCatColors,
  targetEntityId,
  targetName
} from './shared/targetKinds'

defineOptions({
  meta: {
    path: '/cesium/dynamic-targets',
    title: '批量动目标与航迹'
  }
})

const DURATION = 120 // 单次航程的模拟时长（秒）
const START_ISO = '2019-08-19T08:00:00Z'

/** 默认 100（需求点名）。上限 1000 见文件头「环境限制」说明 */
const count = ref(100)
const multiplier = ref(20)
/**
 * 航迹拖尾时长（秒，**模拟时间**）。单次航程 DURATION = 120s，
 * 所以 30s 拖尾 ≈ 航程的 1/4 —— 在「整个目标阵列」这个视距下才看得见；
 * 原先默认 12s 只占 1/10，屏幕上短到几乎与点重合。
 */
const trailTime = ref(30)
/**
 * 是否显示名称标牌。默认**开**（需求点名「每个目标显示图标和名称」）；
 * 但千级标牌在软渲染下开销可观、且在远视距会糊成一片，所以给一个总开关。
 */
const showName = ref(true)
/** 布局种子：点「重新生成」就换一个 —— 目标位置/航向/高度/航程整体重排 */
const seed = ref(20260915)
/** 播放态。⚠️ 只作**显示**用，真值以 \`viewer.clock.shouldAnimate\` 为准（见 syncPlaying） */
const playing = ref(true)
const current = ref(0)
const visibleCount = ref(0)
const fps = ref('--')

/** 各类别「总目标数」（图例展示，随数量滑块变化） */
const catTotal = reactive<Record<string, number>>(
  Object.fromEntries(CAT_KEYS.map((k) => [k, 0]))
)
/** 各类别显隐 —— 与实体的 \`entity.show\` 同步（见 setCatVisible） */
const catVisible = reactive<Record<string, boolean>>(
  Object.fromEntries(CAT_KEYS.map((k) => [k, true]))
)

/**
 * 各类别的**当前配色**（唯一真源）。初始 = 出厂色，用户用图例里的取色器改。
 *
 * ⚠️ 为什么不直接用 \`CATS[i].color\`：那是**出厂值**，是"恢复默认"要回到的常量。
 *    把用户选择写回 \`CATS\` 会让"默认"这个概念消失（恢复默认时无从恢复），
 *    也会污染内核那份被 Node 判据引用的表。
 */
const catColor = reactive<Record<string, string>>(resolveCatColors())

/** 是否已有类别被改成非出厂色 —— 「恢复默认」按钮的可用态 */
const hasCustomColor = computed(() => CAT_KEYS.some((k) => isCustomColor(catColor, k)))

/**
 * 取色器里的预设色板：与出厂色同族但**明显可区分**，方便一眼看出"确实换了色"。
 * (纯白/纯黑刻意不放：图标是实心填充，纯白在浅色影像上会糊、纯黑与描边刻线同色。)
 */
const PRESET_COLORS = [
  '#59e1ff',
  '#8de38b',
  '#ffb74d',
  '#ff8a80',
  '#ffd166',
  '#f06292',
  '#b388ff',
  '#4dd0e1',
  '#aed581',
  '#ff7043'
]

let viewer: any = null
let dataSource: Cesium.CustomDataSource | undefined
let removePostRender: (() => void) | undefined
/**
 * 「某个类别 → 它的实体」索引。
 *
 * ⚠️ 分类显隐**必须留在同一个 \`CustomDataSource\` 内**、按 \`entity.show\` 逐实体关，
 *   而不是「一个类别一个 DataSource」。原因有二：
 *     ① QA / 探针都以 \`dataSources.get(0).entities.values.length\` 作「实体总数」判据
 *        （既有用例断言默认 100、拉满 1000），拆成多个数据源会把这个判据直接打空；
 *     ② \`entity.show\` 是**真布尔**（不像 \`polygon.show\` / \`path.show\` 会被包成
 *        ConstantProperty），读出来就是真值，QA 能直接判「开关有没有回流」。
 */
const entitiesByCat = new Map<TargetCat, any[]>(CAT_KEYS.map((k) => [k, []]))
/**
 * 名称标牌的显隐 —— 用一个**全体共享**的 CallbackProperty。
 *
 * 为什么不逐实体改 \`e.label.show\`：那是「开关一次改 1000 个对象」，
 * 而这一个实例被所有标牌共用，每帧现算，开销可忽略、且不需要在切换时遍历实体。
 * 取值端记得用 \`getValue()\`：Graphics 上的 \`show\` 被包成属性对象，\`!!\` 恒为真。
 */
const labelShowProp = new Cesium.CallbackProperty(() => showName.value, false)

/* ------------------------------------------------- 布局/命名/筛选：见 shared/targetKinds */
// 原先这里内联了 jitter / nextSeed / Placed / layoutPoints / layoutChecksum 五份实现。
// 它们已整体搬进**零 Cesium 内核** \`shared/targetKinds.ts\`（逐位照搬，未改一个常数），
// 好处是那几条确定性判据终于能在 Node 里跑（\`tools/verify-targetkinds.ts\`），
// 而不是"想验一次就得起无头 Chrome 读像素"。

/* ------------------------------------------------------------------ 生命周期 */

function isViewerAlive() {
  if (!viewer) return false
  return typeof viewer.isDestroyed === 'function' ? !viewer.isDestroyed() : false
}

function init(viewerInstance: any) {
  viewer = viewerInstance

  /**
   * ⚠️ 关掉「数据源无时变数据就掐时钟」的省电机制（硬约定，踩坑全集 §14.1）。
   *
   * 源码实证（\`public/libs/Cesium/index.js\`）：
   *   \`_onTick = function (e) { let t = e.currentTime, n = this._dataSourceDisplay.update(t);
   *      this._allowDataSourcesToSuspendAnimation && this._canAnimateUpdateCallback(n); … }\`
   * 也就是说把 \`_allowDataSourcesToSuspendAnimation\` 置 false 后，**\`clock.canAnimate\`
   * 从此再不会被写**；而 \`Clock.tick\` 的推进分支门是 \`canAnimate && _shouldAnimate\`。
   * 本页四类目标可能被整类关掉（\`entity.show = false\`），「当前可见的时变数据」为空时
   * \`dataSourceDisplay.update\` 会返回 false ⇒ 时钟停摆；再打开某类时目标静止不动。
   * 最阴的是读数：\`shouldAnimate\` 的 getter 只返回 \`_shouldAnimate\`、**不含 \`canAnimate\`**，
   * 所以「点开始播放后 shouldAnimate === true」照样全绿 —— 判据必须看 \`currentTime\` 真的推进。
   */
  viewer.allowDataSourcesToSuspendAnimation = false
  viewer.clock.canAnimate = true

  // 时间轴：固定起止时间，由 clock 驱动所有目标。
  //
  // ⚠️ 必须把 clockRange 设成 LOOP_STOP —— 这是本页最容易「零报错但看不到东西」的坑：
  //    Cesium 的 clockRange 默认是 UNBOUNDED，时钟**跑过 stopTime 之后会继续往前走**。
  //    而 SampledPositionProperty 在采样区间之外 getValue() 返回的是 **undefined**
  //    （不是报错、也不是回退到端点）→ 每个目标的 position 都变 undefined →
  //    对应的图标、标牌和航迹**一起消失**。默认 20× 倍速下 120s 的数据 6 真实秒就跑完，
  //    表现为「刚打开页面还能看到，几秒后目标全没了」。
  //    LOOP_STOP 让时钟到 stopTime 后回到 startTime 循环，演示可以一直跑。
  const start = Cesium.JulianDate.fromIso8601(START_ISO)
  const stop = Cesium.JulianDate.addSeconds(start, DURATION, new Cesium.JulianDate())
  viewer.clock.startTime = start.clone()
  viewer.clock.stopTime = stop.clone()
  viewer.clock.currentTime = start.clone()
  viewer.clock.clockRange = Cesium.ClockRange.LOOP_STOP
  viewer.clock.multiplier = multiplier.value
  viewer.clock.shouldAnimate = true
  /**
   * ⚠️ **Timeline 的可见区间在构造时就被锁成「默认 24h」，不随 clock 改**（踩坑全集 §3.10）。
   *    不显式 \`zoomTo\` 的话，底下时间轴显示的是「今天」，而目标的任务时间是 2019-08-19 ——
   *    拖时间轴与画面完全对不上（截图里看得一清二楚：轴上是 Sep 2026，模型是 2019）。
   *    播放控制既然暴露了「时间」，这条就必须一起修，否则时间轴是个摆设。
   */
  if (viewer.timeline) viewer.timeline.zoomTo(start, stop)

  dataSource = new Cesium.CustomDataSource('dynamic-targets')
  viewer.dataSources.add(dataSource)

  removePostRender = viewer.scene.postRender.addEventListener(onPostRender)
  // 相机不在这里写死视角 —— 目标阵列的范围随「目标数量」变化，
  // 固定视角很容易把整片目标框到画面外（实测 300 个目标全部投影到画布外）。
  // 改为 rebuild 后按阵列包围球取景。
  rebuild(true)
  playing.value = !!viewer.clock.shouldAnimate
  exposeProbe()
}

function onPostRender() {
  if (!isViewerAlive()) return
  const now = performance.now()
  fpsFrames++
  if (!fpsAt) fpsAt = now
  if (now - fpsAt >= 1000) {
    fps.value = String(Math.round((fpsFrames * 1000) / (now - fpsAt)))
    fpsFrames = 0
    fpsAt = now
  }
}

/* ------------------------------------------------------------------ 播放控制 */

/**
 * 开始播放 / 暂停播放 / 重新播放 / 重新生成。
 *
 * ⚠️ 每个入口都要**显式重写 \`clock.canAnimate = true\`**：虽然 init 里已经关掉了
 *    省电机制（此后再不改），但只要有人把它开回去（或未来 Cesium 改了写法），
 *    \`canAnimate\` 就会再次被 AND 累加器写 false —— 那时「点开始播放」表现为
 *    \`shouldAnimate\` 变成 true 而画面纹丝不动。重写一次零成本，换来的是
 *    「读数与观感一致」。
 */
function startPlay() {
  if (!isViewerAlive()) return
  viewer.clock.canAnimate = true
  viewer.clock.shouldAnimate = true
  playing.value = true
}

function pausePlay() {
  if (!isViewerAlive()) return
  viewer.clock.shouldAnimate = false
  playing.value = false
}

/** 重新播放：回到起点并立即播放（不重排布局） */
function replay() {
  if (!isViewerAlive()) return
  viewer.clock.currentTime = viewer.clock.startTime.clone()
  startPlay()
}

/** 重新生成：换种子重排全部目标 → 回到起点 → 重新取景 → 立即播放 */
function regenerate() {
  if (!isViewerAlive()) return
  seed.value = nextSeed(seed.value)
  rebuild(true)
  startPlay()
}

function applyClock() {
  if (!isViewerAlive()) return
  viewer.clock.multiplier = multiplier.value
}

/* ------------------------------------------------------------------ 构建 */

/**
 * 重建全部目标。
 * @param reframe 是否重新把相机框到目标阵列上、并把时钟拨回起点
 *                （首次构建、改数量、点「重新生成」时为 true；
 *                 只改航迹时长时为 false，避免视角与时间莫名跳动）
 */
function rebuild(reframe = false) {
  if (!isViewerAlive() || !dataSource) return
  dataSource.entities.removeAll()
  for (const k of CAT_KEYS) {
    entitiesByCat.get(k)!.length = 0
    catTotal[k] = 0
  }

  const start = viewer.clock.startTime.clone()
  const placed = layoutTargets(count.value, seed.value)
  const starts: Cesium.Cartesian3[] = []

  for (const p of placed) {
    const cat = CATS[p.ci]
    const dest = destination(p.lon, p.lat, p.bearing, p.distM)
    const p0 = Cesium.Cartesian3.fromDegrees(p.lon, p.lat, p.alt)
    starts.push(p0)

    const property = new Cesium.SampledPositionProperty()
    property.setInterpolationOptions({ interpolationDegree: 1, interpolationAlgorithm: Cesium.LinearApproximation })
    // 双保险：即使时钟因故越过采样区间（例如用户拖时间轴、或外部改了 clockRange），
    // 也让取值停在端点上，而不是返回 undefined 把目标「弄没」。
    property.forwardExtrapolationType = Cesium.ExtrapolationType.HOLD
    property.backwardExtrapolationType = Cesium.ExtrapolationType.HOLD
    property.addSample(start, p0)
    property.addSample(
      Cesium.JulianDate.addSeconds(start, DURATION / 2, new Cesium.JulianDate()),
      Cesium.Cartesian3.fromDegrees(
        (p.lon + dest.lon) / 2,
        (p.lat + dest.lat) / 2,
        p.alt + (cat.key === 'ship' ? 0 : 1500)
      )
    )
    property.addSample(
      Cesium.JulianDate.addSeconds(start, DURATION, new Cesium.JulianDate()),
      Cesium.Cartesian3.fromDegrees(dest.lon, dest.lat, p.alt + (cat.key === 'ship' ? 0 : 300))
    )

    // 配色取**当前值**（不是出厂值）：用户改过色之后重建（改数量 / 重新生成）必须保持所选色
    const hex = catColor[cat.key]
    const color = Cesium.Color.fromCssColorString(hex)
    // 名称与 id 都走内核（\`targetName\` / \`targetEntityId\`）—— 只在 Node 里被断言一次，页面别另拼一套
    const name = targetName(cat, p.j)

    const entity = dataSource.entities.add({
      id: targetEntityId(cat, p.j),
      // 类别显隐的载体：真布尔，可直接读写（见 entitiesByCat 的注释）
      show: catVisible[cat.key],
      position: property,
      // 图标：按**当前**类别色程序化绘制（零新增静态资源），**机头朝上**绘制
      billboard: {
        image: iconFor(cat.key, hex),
        /**
         * 40px 起步（再乘 \`scaleByDistance\`）—— 尺寸不是为了「大」，是为了让图标在屏幕上
         * 留下**足量的纯类别色像素**：图标是 64×64 画布缩显的，缩得越小、抗锯齿吃掉的比例越高，
         * 「按类别色数像素」这条判据就越数不出东西（半透明 + 32px 版本实测只剩 2.5 px/目标）。
         */
        width: 40,
        height: 40,
        verticalOrigin: Cesium.VerticalOrigin.CENTER,
        horizontalOrigin: Cesium.HorizontalOrigin.CENTER,
        /**
         * 图标朝向 = 目标航向。
         *
         * 图标是「机头朝上（−Y）」画的，所以只要把「上」转到航向即可。
         * \`alignedAxis = Cartesian3.UNIT_Z\` 是 Cesium 的特例语义：「billboard 的上方向
         * 对齐到**当地正北**」；在这个前提下 \`rotation = 0\` 即为「机头朝正北」，
         * 顺航向（顺时针为正，正北为 0）旋转就需要 **−航向**（\`rotation\` 逆时针为正）。
         *
         * 为什么不用 \`TargetTracks\` 那套「逐帧把世界方向投影到屏幕再算角度」：
         * 那是为了在**任意机位**下都对齐屏幕上的移动方向（屏幕空间）。本页的目标簇
         * 是俯视全景、且要扛 1000 个目标，常量旋转零每帧开销，观感已经正确。
         */
        alignedAxis: Cesium.Cartesian3.UNIT_Z,
        rotation: -Cesium.Math.toRadians(p.bearing),
        // 拉开距离时略缩，避免远视距下糊成一团（近处维持原尺寸）
        scaleByDistance: new Cesium.NearFarScalar(20000, 1.0, 1400000, 0.72),
        disableDepthTestDistance: Number.POSITIVE_INFINITY
      },
      // 名称标牌：与图标同色，带半透明暗底（纯色文字直接压在卫星影像上会糊）
      label: {
        text: name,
        font: '12px sans-serif',
        fillColor: color,
        /**
         * **不描边**，只靠底下的暗色块保可读性。
         * 原先照搬 \`TargetTracks\` 的 \`outlineWidth: 3\` —— 那是给 12px 字配的，
         * 到了本页（\`scaleByDistance\` 缩放后实际 ~10px）描边会把**笔画芯整个吃掉**：
         * 远看是一团团黑糊字，而且按类别色数像素时一个纯色像素都数不到
         * （「显示名称」这个开关就失去了像素级判据）。暗底 + 纯填充才是这个字号的正解。
         */
        style: Cesium.LabelStyle.FILL,
        showBackground: true,
        backgroundColor: Cesium.Color.fromCssColorString('rgba(8,18,29,0.78)'),
        backgroundPadding: new Cesium.Cartesian2(6, 4),
        // 标牌挂在图标**下方**（图标 40px ⇒ 偏移 26px 刚好不压住）
        verticalOrigin: Cesium.VerticalOrigin.TOP,
        pixelOffset: new Cesium.Cartesian2(0, 26),
        scaleByDistance: new Cesium.NearFarScalar(20000, 1.0, 1400000, 0.85),
        disableDepthTestDistance: Number.POSITIVE_INFINITY,
        // 共享 CallbackProperty：一个实例被所有标牌共用，「显示名称」总开关才有响应
        show: labelShowProp
      },
      path: new Cesium.PathGraphics({
        resolution: 1,
        leadTime: 0,
        trailTime: trailTime.value,
        width: 2,
        material: color.withAlpha(0.6)
      })
    })
    entitiesByCat.get(cat.key)!.push(entity)
    catTotal[cat.key]++
  }

  current.value = dataSource.entities.values.length
  recountVisible()
  if (reframe) {
    // 重新生成 / 改数量时把时钟拨回起点，打开页面就能看到目标的初始位置
    viewer.clock.currentTime = viewer.clock.startTime.clone()
    frameToTargets(starts)
  }
}

/**
 * 把相机取景到目标阵列的包围球上。
 *
 * 为什么必须这么做：原来写死的 setView(126,42,2600km, pitch -40°) 在 300 个目标下
 * 把**全部 300 个目标都投影到了画布之外**（实测首个目标屏幕坐标 (-439, 986)，
 * 画布只有 686×501）→ 位置解析正常、实体数也对，但一个都看不见。
 * 用包围球取景后，无论目标数量（100~1000）和阵列范围怎么变都能框住。
 */
function frameToTargets(points: Cesium.Cartesian3[]) {
  if (!isViewerAlive() || !points.length) return
  const sphere = Cesium.BoundingSphere.fromPoints(points)
  viewer.camera.viewBoundingSphere(
    sphere,
    new Cesium.HeadingPitchRange(0, Cesium.Math.toRadians(-58), Math.max(sphere.radius * 2.2, 600000))
  )
}

/**
 * 按类别显隐 —— 遍历该类别实体逐个写 \`entity.show\`。
 *
 * 只写这一个字段就够：图标、名称、航迹都挂在同一个 Entity 上，
 * Entity 级 \`show\` 会一并作用到它们（这也是**不要**去逐个关
 * \`billboard.show\` / \`path.show\` 的原因 —— 那些是属性对象，写起来更绕且容易漏）。
 */
function setCatVisible(key: TargetCat, on: boolean) {
  if (catVisible[key] === on) return
  catVisible[key] = on
  const list = entitiesByCat.get(key)
  if (list) for (const e of list) e.show = on
  // 全部关掉再打开时，省电机制可能已经把 canAnimate 写成 false（见 init 的注释）
  if (isViewerAlive()) viewer.clock.canAnimate = true
  recountVisible()
}

function recountVisible() {
  let v = 0
  for (const k of CAT_KEYS) if (catVisible[k]) v += catTotal[k]
  visibleCount.value = v
}

/* ------------------------------------------------------------------ 配色 */

/**
 * 用户改某一类的颜色。
 *
 * \`raw\` 是 \`el-color-picker\` 给的值：\`'#rrggbb'\` 或 **\`null\`**（用户点了"清除"）。
 * 语义定死：
 *   · 合法色 → 生效；
 *   · \`null\` / 空串（清除）→ **回到该类出厂色**（不是变白，也不是保持不变）；
 *   · 其它非法字符串 → 忽略（不写状态），因为 \`Color.fromCssColorString\` 遇非法值
 *     会**静默返回白色**，收了就等于把图标悄悄变白。
 */
function setCatColor(key: TargetCat, raw: unknown) {
  const cleared = raw == null || raw === ''
  const next = cleared ? DEFAULT_CAT_COLORS[key] : normalizeHex(raw)
  if (!next || next === catColor[key]) return
  catColor[key] = next
  applyCatColor(key)
}

/**
 * 把某一类的颜色写到**该类的每一个实体**上（图标 / 标牌 / 航迹三处）。
 *
 * ⚠️ 图标色是**烤进画布**的（\`paintIcon\` 用 \`fillStyle = color\` 画），所以改色必须
 *    **重画图标并重新赋 \`billboard.image\`**；不能用 \`billboard.color\` 去"染"——
 *    那是**乘法**着色，会把同色的刻线一起染掉，且与"同类同色"的判据口径不一致。
 *    \`iconFor\` 对同 (类,色) 返回逐字节相同的 dataURI（走缓存），所以同色重建不会抖。
 *
 * ⚠️ 只遍历**该类别**的实体：1000 个目标时改一类 = 250 次赋值，不是 1000 次。
 */
function applyCatColor(key: TargetCat) {
  if (!isViewerAlive()) return
  const hex = catColor[key]
  const color = Cesium.Color.fromCssColorString(hex)
  const image = iconFor(key, hex)
  const list = entitiesByCat.get(key)
  if (!list) return
  for (const e of list) {
    if (e.billboard) e.billboard.image = image
    if (e.label) e.label.fillColor = color
    // 航迹与类别同色（半透明），否则改色后航迹还是老颜色
    if (e.path) e.path.material = color.withAlpha(0.6)
  }
}

/** 恢复四类出厂配色（只处理被改过的那几类） */
function resetColors() {
  for (const k of CAT_KEYS) {
    if (!isCustomColor(catColor, k)) continue
    catColor[k] = DEFAULT_CAT_COLORS[k]
    applyCatColor(k)
  }
}

/** 由起点、方位角、距离求终点经纬度（球面近似） */
function destination(lon: number, lat: number, bearingDeg: number, distanceMeters: number) {
  const R = 6371000
  const δ = distanceMeters / R
  const θ = Cesium.Math.toRadians(bearingDeg)
  const φ1 = Cesium.Math.toRadians(lat)
  const λ1 = Cesium.Math.toRadians(lon)
  const φ2 = Math.asin(Math.sin(φ1) * Math.cos(δ) + Math.cos(φ1) * Math.sin(δ) * Math.cos(θ))
  const λ2 = λ1 + Math.atan2(Math.sin(θ) * Math.sin(δ) * Math.cos(φ1), Math.cos(δ) - Math.sin(φ1) * Math.sin(φ2))
  return { lon: Cesium.Math.toDegrees(λ2), lat: Cesium.Math.toDegrees(φ2) }
}

/**
 * 探针：把页面状态**显式报出来**供 QA / 排查读。
 *
 * 刻意提供 \`countColor\`：\`entity.show\` 读出来是真的，但「画上了屏」只能靠像素证明。
 * 按类别色数像素是本页唯一能同时抓住「类别显隐没生效」和
 * 「图标/Billboard 根本没上屏」的判据（实体存在、show 全绿、零报错也可能零像素）。
 *
 * 另提供纯函数 \`layout(seed, n)\` / \`layoutChecksum\`，让「重新生成」有**不依赖浏览器**的
 * 强判据：同种子两次必一致、换种子必不同、点按钮后当前布局校验和必变。
 */
function exposeProbe() {
  const hook: any = () => {
    if (!isViewerAlive()) return null
    const ds = viewer.dataSources.get(0)
    const ents = ds ? ds.entities.values : []
    const t = viewer.clock.currentTime
    let bill = 0
    let lab = 0
    let labVis = 0
    let pth = 0
    let shown = 0
    const iconLen: Record<string, number> = {}
    for (const e of ents) {
      if (e.billboard) {
        bill++
        const img = typeof e.billboard.image === 'string' ? e.billboard.image : e.billboard.image?.getValue?.(t)
        if (typeof img === 'string' && img.startsWith('data:image')) {
          const cat = String(e.id).split('-')[1]
          iconLen[cat] = img.length
        }
      }
      if (e.label) {
        lab++
        // ⚠️ Graphics 上的 show 是属性对象，\`!!\` 恒为真 —— 必须 getValue
        if (e.label.show?.getValue?.(t)) labVis++
      }
      if (e.path) pth++
      if (e.show) shown++
    }
    const cats: Record<string, any> = {}
    for (const c of CATS) {
      const list = entitiesByCat.get(c.key) || []
      cats[c.key] = {
        label: c.label,
        // ⚠️ 报**当前**配色，不是出厂配色：探针要能证明"改色真的写进去了"，
        //    报出厂值的话改色前后读数一样，判据就成了真空的。
        color: catColor[c.key],
        defaultColor: DEFAULT_CAT_COLORS[c.key],
        custom: isCustomColor(catColor, c.key),
        total: list.length,
        visible: list.filter((e: any) => e.show).length,
        on: catVisible[c.key]
      }
    }
    return {
      total: ents.length,
      shown,
      catOrder: CAT_KEYS,
      cats,
      showName: showName.value,
      hasBillboard: bill,
      hasLabel: lab,
      labelVisible: labVis,
      hasPath: pth,
      iconLen,
      trailTime: trailTime.value,
      count: count.value,
      seed: seed.value,
      layoutChecksum: layoutChecksum(layoutTargets(count.value, seed.value)),
      playing: playing.value,
      fps: fps.value,
      clock: {
        multiplier: viewer.clock.multiplier,
        shouldAnimate: !!viewer.clock.shouldAnimate,
        canAnimate: !!viewer.clock.canAnimate,
        curSec: Cesium.JulianDate.toDate(t).getTime() / 1000,
        startSec: Cesium.JulianDate.toDate(viewer.clock.startTime).getTime() / 1000,
        stopSec: Cesium.JulianDate.toDate(viewer.clock.stopTime).getTime() / 1000
      }
    }
  }
  hook.setCat = (k: TargetCat, on: boolean) => {
    setCatVisible(k, on)
    return hook()
  }
  hook.catColor = (k: TargetCat) => catColor[k] || '#ffffff'
  /** 改色直通（供探针/QA 做像素级验收：改色后旧色像素应归零、新色像素应出现） */
  hook.setCatColor = (k: TargetCat, hex: string | null) => {
    setCatColor(k, hex)
    return hook()
  }
  hook.resetColors = () => {
    resetColors()
    return hook()
  }
  hook.defaultColors = () => ({ ...DEFAULT_CAT_COLORS })
  /** 纯函数直通：QA 可以在**不起浏览器**的前提下验布局的确定性与种子敏感性 */
  hook.layout = (s: number, n: number) => layoutChecksum(layoutTargets(n, s))
  hook.play = () => {
    startPlay()
    return hook()
  }
  hook.pause = () => {
    pausePlay()
    return hook()
  }
  hook.replay = () => {
    replay()
    return hook()
  }
  hook.regenerate = () => {
    regenerate()
    return hook()
  }
  /**
   * 数「某一类别色」的像素（先 \`render()\` 再 \`readPixels\` —— 本工程 preserveDrawingBuffer=false）。
   *
   * ⚠️ 判色**不能用「和源色相差 ≤ N」的平铺容差**（本页实测踩过）：
   *    图标是 64×64 画布缩到 ~32px 上屏的，缩小时纹理按**预乘 alpha**采样，
   *    边缘/细部的每个屏幕像素都是「类别色 × 覆盖率」⇒ 渲染出来是**变暗的类别色**，
   *    而不是源色。实测 \`#59e1ff\` 在 ±20 容差下只剩 165 个像素、放到 ±80 才有 2719 个；
   *    而放宽容差又会把底图植被算成绿色目标（±80 时「无人机绿」虚高到 12237）。
   *
   *    正解 = 按「**p ≈ k·c**（k 为覆盖率）」建模：用最小二乘解出 k，
   *    要求 k ∈ [kMin, 1.06]（至少在 60% 覆盖以上，滤掉「大面积透出底图」的像素），
   *    再看**拟合残差**是否足够小。这样既能吃下变暗，又不会把植被的绿算进来
   *    （植被 #7fa060 对无人机绿 \`#8de38b\` 拟合出的 k≈0.86、残差 34 > 24 ⇒ 不算命中）。
   */
  hook.countColor = (hex: string, tol = 24, kMin = 0.6) => {
    if (!isViewerAlive()) return null
    const c = viewer.scene.context
    viewer.render()
    const W = c.drawingBufferWidth
    const H = c.drawingBufferHeight
    const buf = c.readPixels({ x: 0, y: 0, width: W, height: H })
    const m = /^#?([0-9a-fA-F]{6})$/.exec(hex)
    if (!m) return null
    const v = parseInt(m[1], 16)
    const R = (v >> 16) & 255
    const G = (v >> 8) & 255
    const B = v & 255
    const norm = R * R + G * G + B * B
    let hit = 0
    for (let i = 0; i < buf.length; i += 4) {
      const pr = buf[i]
      const pg = buf[i + 1]
      const pb = buf[i + 2]
      const k = (pr * R + pg * G + pb * B) / norm
      if (k < kMin || k > 1.06) continue
      if (
        Math.abs(pr - k * R) <= tol &&
        Math.abs(pg - k * G) <= tol &&
        Math.abs(pb - k * B) <= tol
      ) {
        hit++
      }
    }
    return { hex, hit, w: W, h: H }
  }
  ;(window as any).__dynTargets = hook
}

let fpsFrames = 0
let fpsAt = 0

onBeforeUnmount(() => {
  removePostRender?.()
  removePostRender = undefined
  if (isViewerAlive()) {
    // 必须先停时钟：否则 Cesium 的 tick 会继续驱动已经销毁的场景
    viewer.clock.shouldAnimate = false
    if (dataSource) viewer.dataSources.remove(dataSource, true)
  }
  dataSource = undefined
  for (const k of CAT_KEYS) entitiesByCat.get(k)!.length = 0
  delete (window as any).__dynTargets
  viewer = null
})
