      const c = Cesium.SceneTransforms.worldToWindowCoordinates(
        viewer.scene,
        Cesium.Cartesian3.fromDegrees(lon, lat, h)
      )
      if (!c) return null
      const r = viewer.canvas.getBoundingClientRect()
      return { x: c.x + r.left, y: c.y + r.top }
