      const c = turf.centerOfMass(f as any)
      const a = turf.area(f as any) / 1e6
      const lon = c.geometry.coordinates[0] as number
      const lat = c.geometry.coordinates[1] as number
      if (!isFinite(lon) || !isFinite(lat) || !isFinite(a) || a <= 0) continue
      out.push({ lon, lat, v: a })
