  const syn = makeSynthetic({ kind: config.kind, n: config.n, seed: config.seed, region: SYNTH_REGION })
  const kindNote =
    config.kind === 'linear'
      ? '线性趋势面：开「漂移项」后泛克里金应精确复现（RMSE≈0），关掉则明显有残差 —— 这是漂移是否真的接上的判据'
      : config.kind === 'wave'
        ? '正弦波动：既非趋势也非孤立峰，用于一般情形'
        : '高斯热点：局部异常，克里金应比 IDW 更贴合峰值'
  return { samples: syn.samples, note: kindNote }
