defineOptions({ meta: { path: '/cesium/plot-track', title: '点迹-航迹处理链（量测/门限/关联/滤波）' } })

/* ══════════════════════════════════════════════════════════════════════
 * 常量
 * ══════════════════════════════════════════════════════════════════════ */

/** 站心（与二十二期各页同一处上海站，便于互相对照） */
const ORIGIN_LON = 121.4735
