import * as Cesium from 'cesium'
import Globe from '@/gis/cesium/index.vue'
import { nextTick, onBeforeUnmount, reactive, ref } from 'vue'
import { sampleProfile, waitForTerrain, type ProfileSample } from './shared/terrain'

defineOptions({
  meta: {
    path: '/cesium/profile',
    title: '剖面分析'
  }
})

const samples = ref<ProfileSample[]>([])
const chartRef = ref<HTMLCanvasElement | null>(null)
const terrainReady = ref(false)
const tip = ref('正在等待地形加载…')
