import * as Cesium from 'cesium'
import Globe from '@/gis/cesium/index.vue'
import { onBeforeUnmount, ref, watch } from 'vue'
import {
  TRAIL_PRESETS,
  genTracks,
  tracksSpan,
  visiblePoints,
  type Track,
  type TrailMode
} from './shared/trackTime'

defineOptions({
  meta: {
    path: '/cesium/track-time',
    title: '时序轨迹'
  }
})

/** 页面速度档（不用 \`timelineClock.SPEED_STEPS\`：那套是给"几天跨度的卫星"用的，本页总长 ~4 min） */
const SPEEDS = [0.5, 1, 2, 5, 10] as const

const speedIdx = ref(3) // 5×
const trailIdx = ref(1) // 30 s
const trackCount = ref(12)
const pointsPer = ref(121)
const looping = ref(true)
const showHead = ref(true)
const playing = ref(true)
const busy = ref(false)
const error = ref('')
const tip = ref('准备中…')

const elapsed = ref(0)
const duration = ref(1)
const drawnTotal = ref(0)
const totalVerts = ref(0)
const maxPerTrack = ref(0)
const progress = ref(0)

const speed = ref(SPEEDS[speedIdx.value])

let viewer: any = null
let tracks: Track[] = []
/** 每条轨迹**当前已绘制的顶点数**（用来判断要不要重建折线几何） */
