import * as Cesium from 'cesium'
import type { Viewer } from 'cesium2s'
import Globe from '@/gis/cesium/index.vue'
import { onBeforeUnmount, ref } from 'vue'
import { attachVideoFromCanvas, createCanvasTexture, createSyntheticFeed } from './shared/videoSource'
import type { CanvasTextureHandle, SyntheticFeed, VideoHandle } from './shared/videoSource'

