  const radii: number[] = []
  let radiusSum = 0
  let radiusMax = 0
  let visibleCount = 0
  for (let d = 0; d < DIRS; d++) {
    let maxAngle = -Infinity
    let lastVisibleDist = 0
    for (let r = 1; r <= RINGS; r++) {
      const sample = sampled[d * RINGS + (r - 1)]
      const dist = stepLen * r
      // sampleTerrainMostDetailed 在个别点拿不到数据时 height 会是 undefined/NaN，
      // 一旦混进来会让 angle 变 NaN、比较恒为 false，把这个方向的可见半径钉死在 0，
      // 最终表现为「可见面积占比 0%」这种看起来正常其实全错的结果 → 直接跳过该采样点。
      if (!Number.isFinite(sample.height)) continue
      const dz = (sample.height as number) - obsZ
      const angle = Math.atan2(dz, dist)
      if (angle >= maxAngle) {
        maxAngle = angle
        lastVisibleDist = dist
        visibleCount++
      }
    }
    radii.push(lastVisibleDist)
    const azimuth = (d / DIRS) * Math.PI * 2
    const dLat = (lastVisibleDist * Math.cos(azimuth)) / 111320
    const dLon =
      (lastVisibleDist * Math.sin(azimuth)) / (111320 * Math.max(0.01, Math.cos(observer.latitude)))
    visiblePoints.push(
      Cesium.Cartesian3.fromRadians(observer.longitude + Cesium.Math.toRadians(dLon), observer.latitude + Cesium.Math.toRadians(dLat), 0)
    )
    radiusSum += lastVisibleDist
    radiusMax = Math.max(radiusMax, lastVisibleDist)
  }
